INSERT INTO api_workexperience VALUES(2,'John Lewis & Partners','Technical Support Partner','2022-04-19',NULL,replace(replace('Provide front-line technical support, resolving customer queries and troubleshooting devices (phones, laptops, audio/TV equipment).\r\n\r\nPrepare and process documentation including warranty claims, repairs, and financial adjustments with accuracy and following compliance.\r\n\r\nTrain and support colleagues in adopting new digital tools and systems during the Retail Transformation phase at John Lewis ensuring smooth transition from legacy systems into new ones.','\r',char(13)),'\n',char(10)),'2025-11-14 06:08:37.857242','company_logos/mail_qXRctF6.png.webp');
INSERT INTO api_blogpost VALUES(1,'What is lore Epsom?',replace(replace('Lorem Ipsum is simply dummy text of the printing and typesetting industry. Lorem Ipsum has been the industry''s standard dummy text ever since the 1500s, when an unknown printer took a galley of type and scrambled it to make a type specimen book. \r\n\r\nIt has survived not only five centuries, but also the leap into electronic typesetting, remaining essentially unchanged. It was popularised in the 1960s with the release of Letraset sheets containing Lorem Ipsum passages, and more recently with desktop publishing software like Aldus PageMaker including versions of Lorem Ipsum.','\r',char(13)),'\n',char(10)),'','2025-11-09 15:07:19.665000','');
INSERT INTO api_blogpost VALUES(2,'Why do we use it?',replace(replace('It is a long established fact that a reader will be distracted by the readable content of a page when looking at its layout. The point of using Lorem Ipsum is that it has a more-or-less normal distribution of letters, as opposed to using ''Content here, content here'', making it look like readable English.\r\n\r\nMany desktop publishing packages and web page editors now use Lorem Ipsum as their default model text, and a search for ''lorem ipsum'' will uncover many web sites still in their infancy. Various versions have evolved over the years, sometimes by accident, sometimes on purpose (injected humour and the like).','\r',char(13)),'\n',char(10)),'','2025-11-09 15:12:08.398000','');
INSERT INTO api_blogpost VALUES(3,'Where can I get some?',replace(replace('There are many variations of passages of Lorem Ipsum available, but the majority have suffered alteration in some form, by injected humour, or randomised words which don''t look even slightly believable. If you are going to use a passage of Lorem Ipsum, you need to be sure there isn''t anything embarrassing hidden in the middle of text. \r\n\r\nAll the Lorem Ipsum generators on the Internet tend to repeat predefined chunks as necessary, making this the first true generator on the Internet. It uses a dictionary of over 200 Latin words, combined with a handful of model sentence structures, to generate Lorem Ipsum which looks reasonable. The generated Lorem Ipsum is therefore always free from repetition, injected humour, or non-characteristic words etc.','\r',char(13)),'\n',char(10)),'','2025-11-09 15:31:38.093000','');
INSERT INTO api_blogpost VALUES(4,'Where does it come from?',replace(replace('Contrary to popular belief, Lorem Ipsum is not simply random text. It has roots in a piece of classical Latin literature from 45 BC, making it over 2000 years old. Richard McClintock, a Latin professor at Hampden-Sydney College in Virginia, looked up one of the more obscure Latin words, consectetur, from a Lorem Ipsum passage, and going through the cites of the word in classical literature, discovered the undoubtable source. \r\n\r\nLorem Ipsum comes from sections 1.10.32 and 1.10.33 of "de Finibus Bonorum et Malorum" (The Extremes of Good and Evil) by Cicero, written in 45 BC. This book is a treatise on the theory of ethics, very popular during the Renaissance. The first line of Lorem Ipsum, "Lorem ipsum dolor sit amet..", comes from a line in section 1.10.32.','\r',char(13)),'\n',char(10)),'blog_images/Projectplaceholder.png','2025-11-09 17:49:44.115000','lipsum, test, lorem');
INSERT INTO api_novels VALUES(1,'RED','Shaun Allsopp','Told through shifting perspectives and timelines, RED explores themes of guilt, identity, and whether a person can truly escape their past. Secrets resurface and the line between victim and monster blurs...','novel_covers/Projectplaceholder.png','2025-11-10 20:27:53.436000','mystery, thriller, supernatural');
INSERT INTO api_novels VALUES(3,'Finding Effy','Shaun Allsopp','Part mystery, part coming-of-age adventure, Finding Effy is a story about friendship, courage, and discovering that sometimes the only way to move forward is to unlock the secrets of the past.','novel_covers/Projectplaceholder_8WJKK47.png','2025-11-13 15:52:30.266882','YA, mystery, adventure, coming-of-age');
